import {CAMPAIGN,MATERIALS,SITES,baseURL,siteForPath} from './registry.js';
import {SAVE_KEY,LEGACY_KEY,RECOVERY_KEY,empty,parseJSON,extract,merge,envelope,edit,pack,unpack} from './save-model.js';
import {indexedRecovery} from './recovery.js';
export {SAVE_KEY};

export async function createCampaignStore({storage,events=globalThis.window,recovery=indexedRecovery(),locks=globalThis.navigator?.locks,actor=crypto.randomUUID()}={}){
 const transient=new Map();let storageAccess=true;try{storage??=globalThis.localStorage;}catch{storageAccess=false;}const backend=storage;storage={getItem(key){try{const value=backend?.getItem(key);if(value!=null){transient.set(key,value);return value;}return transient.get(key)??null;}catch{storageAccess=false;return transient.get(key)??null;}},setItem(key,value){transient.set(key,value);if(!backend){storageAccess=false;throw new Error('浏览器不允许本地存储，进度暂留内存，请导出。');}backend.setItem(key,value);}};
 let state=empty(),status={persistent:true,recovery:true,message:''},queue=Promise.resolve(),disposed=false;const listeners=new Set();
 const read=()=>storage.getItem(SAVE_KEY);
 const emit=meta=>{if(!disposed)for(const fn of listeners)fn(state,{...meta,status});};
 async function recovered(){const candidates=[];try{const p=await recovery.get();const raw=await unpack(p);if(extract(raw))candidates.push(extract(raw));}catch{status.recovery=false;}try{const p=parseJSON(storage.getItem(RECOVERY_KEY));const raw=await unpack(p);if(extract(raw))candidates.push(extract(raw));}catch{}return candidates.reduce(merge,empty());}
 async function ensureLegacy(raw){const prior=storage.getItem(LEGACY_KEY);if(prior){if(backend&&backend.getItem(LEGACY_KEY)!==prior)storage.setItem(LEGACY_KEY,prior);if(!await unpack(parseJSON(prior)))throw new Error('旧档归档校验失败，未覆盖活动存档。');return;}const snapshot=await pack(raw??'null');storage.setItem(LEGACY_KEY,JSON.stringify(snapshot));if(await unpack(parseJSON(storage.getItem(LEGACY_KEY)))!==snapshot.raw)throw new Error('旧档备份未通过回读校验。');}
 async function persist(){const raw=read(),root=parseJSON(raw);if(root?.save_schema>4)throw new Error('此存档来自更新版本，已停止写入。');state=merge(state,extract(raw)||empty());await ensureLegacy(raw);const output=JSON.stringify(envelope(state,raw));if(!extract(output))throw new Error('新版存档校验失败。');const checkpoint=await pack(output);let checkpointOK=false;try{await recovery.set(checkpoint);checkpointOK=true;}catch{status.recovery=false;}try{storage.setItem(RECOVERY_KEY,JSON.stringify(checkpoint));checkpointOK=true;}catch{}if(!checkpointOK)throw new Error('无法建立恢复快照，进度暂留在内存；请导出。');storage.setItem(SAVE_KEY,output);if(!extract(read()))throw new Error('活动存档回读失败。');status.persistent=true;status.message=status.recovery?'':'IndexedDB不可用，恢复快照暂存本地；建议导出。';}
 async function run(fn){const operation=async()=>{try{return await fn();}catch(error){status={...status,persistent:false,message:error.message||'本地存储不可用，请导出进度。'};emit({kind:'storage-error'});return {ok:false,message:status.message};}};return locks?.request?locks.request('qinghe-v4-save',operation):operation();}
 const schedule=fn=>{queue=queue.then(()=>run(fn),()=>run(fn));return queue;};
 await schedule(async()=>{const raw=read();if(parseJSON(raw)?.save_schema>4)throw new Error('此存档来自更新版本，已停止写入。');const active=extract(raw);state=active||await recovered();await ensureLegacy(raw);await persist();});
 function commit(kind,mutation){return schedule(async()=>{state=merge(state,extract(read())||empty());const result=await mutation();if(result?.ok===false)return result;await persist();emit({kind,result});return result||{ok:true};});}
 async function receive(e){if(e.key!==SAVE_KEY&&e.key!==null)return;schedule(async()=>{state=merge(state,extract(read())||empty());await persist();emit({kind:'storage'});});}
 events?.addEventListener('storage',receive);
 return {get:()=>state,status:()=>status,subscribe(fn){listeners.add(fn);return()=>listeners.delete(fn);},async update(bucket,id,value){return commit(bucket,()=>{state=edit(state,bucket,id,value,actor);return {ok:true};});},async collect(id,snapshot){if(!Object.hasOwn(MATERIALS,id))return {ok:false};if(MATERIALS[id].access&&!state.accounts[MATERIALS[id].access]?.value)return {ok:false,message:'该共享范围尚未授权。'};if(state.evidence[id])return {ok:true,duplicate:true};return commit('collect',()=>{if(state.evidence[id])return {ok:true,duplicate:true};state=edit(state,'evidence',id,true,actor);if(snapshot&&!state.snapshots[id])state=edit(state,'snapshots',id,{text:String(snapshot.text||'').slice(0,16000),url:String(snapshot.url||MATERIALS[id].path).slice(0,500)},actor);return {ok:true,id};});},async discover(site){if(!Object.hasOwn(SITES,site))return {ok:false};if(state.discovered_sites.includes(site))return {ok:true,duplicate:true};return commit('discover',()=>{state.discovered_sites.push(site);state.clock++;return {ok:true,site};});},async export(){await queue;return {format:'QH-V4-EXPORT',legacy:parseJSON(storage.getItem(LEGACY_KEY)),checkpoint:await pack(JSON.stringify(envelope(state,read())))};},async restore(input){const x=parseJSON(input);if(x?.format!=='QH-V4-EXPORT')return {ok:false,message:'不是有效的调查本导出文件。'};const raw=await unpack(x.checkpoint);const imported=extract(raw);if(!imported||!await unpack(x.legacy))return {ok:false,message:'文件校验不通过，当前进度未变更。'};return commit('restore',()=>{state=merge(state,imported);state=edit(state,'legacyImports',x.legacy.sha256,x.legacy,actor);return {ok:true,message:'已合并导出文件中的调查记录。'};});},flush:()=>queue,dispose(){disposed=true;events?.removeEventListener('storage',receive);listeners.clear();recovery.close?.();}};
}

// Only actual navigation discovers a site; an unavailable code does not unlock anything.
export async function trackDiscovery(store,{site=document.body.dataset.site,doc=document,location=globalThis.location}={}){await store.discover(site);const root=baseURL(location);const listener=e=>{if(e.defaultPrevented||e.button>1)return;const a=e.target.closest?.('a[href]');if(!a||a.hasAttribute('download'))return;const u=new URL(a.href,location.href);if(u.origin===root.origin&&u.pathname.startsWith(root.pathname))store.discover(siteForPath(u.pathname));};doc.addEventListener('click',listener);doc.addEventListener('auxclick',listener);return ()=>{doc.removeEventListener('click',listener);doc.removeEventListener('auxclick',listener);};}

export async function mountInvestigationDrawer(store,options){const {mountNotebook}=await import('./notebook.js');return mountNotebook(store,options);}
